        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null)
        {
            if (Directory.Exists(Path.Combine(dir.FullName, ".git")) ||
                dir.GetFiles("*.sln").Length > 0 ||
                dir.GetFiles("*.slnx").Length > 0)
                return s_cached = dir.FullName;
            dir = dir.Parent;
